    [7746]={name="Explorers' League Commendation",quality=3,ilvl=41,sourceType="quest_reward",instructions="Reward from the quest 'Mythology of the Titans'. Starts with Librarian Mae Paledust in Ironforge. Objective: Retrieve Mythology of the Titans from the Monastery and bring it to Librarian Mae Paledust in Ironforge.",zone="Scarlet Monastery",questName="Mythology of the Titans",lore="The future is inevitable! We hurl ourselves towards it like falling raindrops to the Great Sea. But perhaps, by studying the past, we can know what to expect and be better prepared for the unknown."},
