    [13262]={name="Ashbringer",quality=5,ilvl=76,reqLevel=60,sourceType="special",instructions="Ashbringer - quest chain.",lore="The blade the Silver Hand carried against the Scourge, and the one Tirion Fordring's order was built around. Corrupted when Renault Mograine used it on his own father, Alexandros, in the Scarlet Monastery.",proc="Chance on hit: Blasts a target for 700 Fire damage."},
