    [19825]={name="Zandalar Freethinker's Breastplate",quality=4,ilvl=65,sourceType="quest_reward",instructions="Reward from the quest 'Paragons of Power: The Freethinker's Breastplate'. Starts with Jin'rokh the Breaker in Stranglethorn Vale. Objective: Bring Jin'rokh the Breaker a Primal Hakkari Tabard. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.Jin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.",zone="Zul'Gurub",questName="Paragons of Power: The Freethinker's Breastplate",lore="They imbue their breastplates with powerful mojo. If their beliefs falter in the face of the enemy, their breastplate will not."},
    [19826]={name="Zandalar Freethinker's Belt",quality=4,ilvl=61,sourceType="quest_reward",instructions="Reward from the quest 'Paragons of Power: The Freethinker's Belt'. Starts with Jin'rokh the Breaker in Stranglethorn Vale. Objective: Bring Jin'rokh the Breaker a Primal Hakkari Shawl. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.Jin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.",zone="Zul'Gurub",questName="Paragons of Power: The Freethinker's Belt",lore="Your beliefs are alien to us, heathen. Ancient Zandalar were once branded as heretics."},
    [19827]={name="Zandalar Freethinker's Armguards",quality=4,ilvl=61,sourceType="quest_reward",instructions="Reward from the quest 'Paragons of Power: The Freethinker's Armguards'. Starts with Jin'rokh the Breaker in Stranglethorn Vale. Objective: Bring Jin'rokh the Breaker Primal Hakkari Bindings. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.Jin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.",zone="Zul'Gurub",questName="Paragons of Power: The Freethinker's Armguards",lore="Heathens have a place in the tribe. Heathens are freethinkers of Zandalar."},
    [19855]={name="Bloodsoaked Legplates",quality=4,ilvl=68,reqLevel=60,sourceType="boss_drop",instructions="Drops from Hakkar.",zone="Zul'Gurub",npc="Hakkar",lore="The Soulflayer, a blood god the Atal'ai priests summoned into Zul'Gurub. He feeds on the blood of his own worshippers, which is the part they had not planned for."},
