    [20650]={name="Desert Wind Gauntlets",quality=2,ilvl=60,sourceType="quest_reward",instructions="Reward from the quest 'Vyral the Vile'. Pick it over the other reward choices. Starts with Huum Wildmane in Silithus. Objective: Bring Vyral's Signet Ring to Huum Wildmane in Cenarion Hold.",zone="Silithus",questName="Vyral the Vile",lore="We have discovered another base of operations for the Twilight's Hammer. It is called Twilight's Run; it is a cave tucked in the northeast corner of Silithus."},
